package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

const MOD = 998244353

func mod(num int64) int64 {
	num %= MOD
	if num < 0 {
		num += MOD
	}
	return num
}

func mul(a, b int64) int64 {
	return (a * b) % MOD
}

func getPrimes(n int) []bool {
	nums := make([]bool, n+1)
	for i := 2; i <= n; i++ {
		nums[i] = true
	}
	primes := []int{}
	for i := 2; i <= n; i++ {
		if nums[i] {
			primes = append(primes, i)
		}
		for _, p := range primes {
			if p*i > n {
				break
			}
			nums[p*i] = false
			if i%p == 0 {
				break
			}
		}
	}
	return nums
}

func solve(n, m int64) int64 {
	p := getPrimes(int(n) + 10)
	pre := int64(1)
	M := mod(m)
	res := int64(0)
	ans := M
	ans1 := M

	for i := int64(2); i <= n; i++ {
		if pre <= m && p[i] {
			pre *= i
		}
		if pre > m {
			ans = 0
		} else {
			ans = mul(ans, m/pre)
		}
		ans1 = mul(ans1, M)
		res = mod(res + ans1 - ans)
	}
	return res
}

